function world(meta: Omit<AuthoredWorld, 'nodes' | 'version' | 'cover' | 'background' | 'adaptation'>, entries: SceneNode[], note: string): AuthoredWorld {
  const art = `/assets/${meta.id}.webp`;
  const nodes = [...entries, ...routesA[meta.id]].map((node) => {
    const choices = [...node.choices, ...(node.id === meta.startNodeId ? routeEntrancesA[meta.id] : []), ...(additionalChoicesA[meta.id]?.[node.id] ?? [])].map((choice) => {
      const text = choiceLabelsA[meta.id][choice.id];
      return text && text !== choice.text ? { ...choice, text, legacyTexts: [...new Set([choice.text, ...(choice.legacyTexts ?? [])])] } : choice;
    });
    const title = titlesA[meta.id][node.id] ?? node.title;
    return [node.id, { ...node, title, ending: node.ending ? { ...node.ending, title } : undefined, choices, background: art }];
  });
  return withCatalogAEditorial({ ...meta, version: '1.0.0', cover: art, background: art, adaptation: { scope: 'based-on-api-excerpt', adultCast: true, note: `基于接口提供的真实节选，非原作全文。新增路线及其结局为游戏原创，保留旧选择的效果与去向。所有登场角色均为成年人。${note}` }, nodes: Object.fromEntries(nodes) });
}

